(5784342, 841787, 98771, '<td valign="top">I like this, the light bouncing off the waves in the BG is a nice effect. Adds to the sense of motion. Well done.</td>', 'I like this, the light bouncing off the waves in the BG is a nice effect. Adds to the sense of motion. Well done.', '2009-12-28 17:57:49.000000', NULL, 1),
(5784350, 841856, 98771, '<td valign="top">Wow, this is nice. I have an idea who this may belong to, can''t wait to see if I''m right.The advanced editing really made it pop. I don''t do this often but from what I''ve seen so far, this is a 10.</td>', 'Wow, this is nice. I have an idea who this may belong to, can''t wait to see if I''m right.The advanced editing really made it pop. I don''t do this often but from what I''ve seen so far, this is a 10.', '2009-12-28 18:02:41.000000', NULL, 1),
(5784356, 841605, 98771, '<td valign="top">Don''t see many of these around here, what a beautiful bird. You''ve done a excellent job capturing it.</td>', 'Don''t see many of these around here, what a beautiful bird. You''ve done a excellent job capturing it.', '2009-12-28 18:09:15.000000', NULL, 1),
(5784362, 841643, 98771, '<td valign="top">This is very nice, I never seem to be able to get close enough to one to come up with an image like this. Well done.</td>', 'This is very nice, I never seem to be able to get close enough to one to come up with an image like this. Well done.', '2009-12-28 18:12:56.000000', NULL, 1),
(5784374, 841911, 98771, '<td valign="top">Absolutely wonderful. Having taken about thousand images of these little guys, I know how tough this had to be. Imho, it needs to be wearing a ribbon at the end of the challenge.10</td>', 'Absolutely wonderful. Having taken about thousand images of these little guys, I know how tough this had to be. Imho, it needs to be wearing a ribbon at the end of the challenge.10', '2009-12-28 18:21:51.000000', NULL, 1),
(5784383, 841963, 52713, '<td valign="top">great colors, looks like it might be a severe crop or over-sharpened a little. 7</td>', 'great colors, looks like it might be a severe crop or over-sharpened a little. 7', '2009-12-28 18:34:53.000000', NULL, 1),
