(5784411, 841888, 52713, '<td valign="top">saw these when I was at Canon Beach in Oregon lest time. nice use of negative space.</td>', 'saw these when I was at Canon Beach in Oregon lest time. nice use of negative space.', '2009-12-28 18:44:13.000000', NULL, 1),
(5784412, 841781, 52713, '<td valign="top">I love cardinals. nice capture</td>', 'I love cardinals. nice capture', '2009-12-28 18:44:32.000000', NULL, 1),
