(5784428, 841960, 52713, '<td valign="top">classic duck capture.</td>', 'classic duck capture.', '2009-12-28 18:48:26.000000', NULL, 1),
(5784459, 841980, 60047, '<td valign="top">I really like the deep greens contrasting with the white subject. The fact that the subject is taking a step is really cool.I''m not sure if he is just slightly out of focus or that you didn''t sharpen the image in post processing but I would have preferred to view the subject with better detail definition.</td>', 'I really like the deep greens contrasting with the white subject. The fact that the subject is taking a step is really cool.I''m not sure if he is just slightly out of focus or that you didn''t sharpen the image in post processing but I would have preferred to view the subject with better detail definition.', '2009-12-28 19:26:38.000000', NULL, 1),
(5784461, 841326, 60047, '<td valign="top">Great definition on the feathers. Nice work.</td>', 'Great definition on the feathers. Nice work.', '2009-12-28 19:29:07.000000', NULL, 1),
(5784463, 841779, 60047, '<td valign="top">The water has really made for a beautiful backdrop.</td>', 'The water has really made for a beautiful backdrop.', '2009-12-28 19:30:18.000000', NULL, 1),
(5784465, 841723, 112828, '<td valign="top">From the angle this can''t be a 500mm shot, unless the shooter is on top of a rather tall building or hill..<br/> <br/>Nice work getting this close.<br/> <br/>Oh, and very nice shot too!</td>', 'From the angle this can''t be a 500mm shot, unless the shooter is on top of a rather tall building or hill.. Nice work getting this close. Oh, and very nice shot too!', '2009-12-28 19:32:14.000000', NULL, 1),
(5784467, 841645, 60047, '<td valign="top">I really like what you''ve done with this. I am curious - with this particular species, I am guessing you rotated the shot 90 degrees clockwise? If so, that''s really a great choice - if not, I am impressed with this bird''s strength. In either case, this is quite a powerful and unique silhouette.</td>', 'I really like what you''ve done with this. I am curious - with this particular species, I am guessing you rotated the shot 90 degrees clockwise? If so, that''s really a great choice - if not, I am impressed with this bird''s strength. In either case, this is quite a powerful and unique silhouette.', '2009-12-28 19:34:41.000000', NULL, 1),
(5784468, 841390, 60047, '<td valign="top">Nice capture. Great colors.</td>', 'Nice capture. Great colors.', '2009-12-28 19:35:59.000000', NULL, 1),
(5784469, 841924, 60047, '<td valign="top">Great idea. I think an even closer crop would be more powerful.</td>', 'Great idea. I think an even closer crop would be more powerful.', '2009-12-28 19:36:47.000000', NULL, 1),
(5784470, 841068, 60047, '<td valign="top">Wow, what a capture. Nice work.</td>', 'Wow, what a capture. Nice work.', '2009-12-28 19:37:14.000000', NULL, 1),
(5784471, 841455, 60047, '<td valign="top">I love the red BG. This shot is great without it - but quite stunning with it.</td>', 'I love the red BG. This shot is great without it - but quite stunning with it.', '2009-12-28 19:38:11.000000', NULL, 1),
(5784477, 841621, 60047, '<td valign="top">Wonderfully eerie body shape under those wings.</td>', 'Wonderfully eerie body shape under those wings.', '2009-12-28 19:39:13.000000', NULL, 1),
(5784484, 841828, 60047, '<td valign="top">Wonderful bokeh in the BG. Would have preferred a little more fill light for his left side (you may have already pushed this as far as possible in post processing.) Nice capture.</td>', 'Wonderful bokeh in the BG. Would have preferred a little more fill light for his left side (you may have already pushed this as far as possible in post processing.) Nice capture.', '2009-12-28 19:43:31.000000', NULL, 1),
(5784485, 841615, 60047, '<td valign="top">Wonderful water. Great DOF. Nice crisp focus.</td>', 'Wonderful water. Great DOF. Nice crisp focus.', '2009-12-28 19:44:06.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5784487, 841485, 60047, '<td valign="top">What a neat capture - and a nice complimentary title to the shot!</td>', 'What a neat capture - and a nice complimentary title to the shot!', '2009-12-28 19:44:53.000000', NULL, 1),
(5784489, 841626, 60047, '<td valign="top">Great definition on the feathers. Wonderful taupe BG tones.</td>', 'Great definition on the feathers. Wonderful taupe BG tones.', '2009-12-28 19:46:02.000000', NULL, 1),
(5784492, 841726, 60047, '<td valign="top">What an incredible capture. The orange and yellow look just slightly over saturated. I love the contrast in colors between the rich blue BG and the subject.</td>', 'What an incredible capture. The orange and yellow look just slightly over saturated. I love the contrast in colors between the rich blue BG and the subject.', '2009-12-28 19:47:31.000000', NULL, 1),
(5784496, 841543, 60047, '<td valign="top">Amazing capture. I''m sure you are hearing about the grain/noise - a result of the cropping I assume - I had a similar problem with my submission. Doesn''t take away from the fact that you snatched a great photographic moment, here. Ahh, but if only I had several thousand to unload on a 500mm lens! Nice work.</td>', 'Amazing capture. I''m sure you are hearing about the grain/noise - a result of the cropping I assume - I had a similar problem with my submission. Doesn''t take away from the fact that you snatched a great photographic moment, here. Ahh, but if only I had several thousand to unload on a 500mm lens! Nice work.', '2009-12-28 19:50:51.000000', NULL, 1),
(5784500, 841910, 60047, '<td valign="top">Great clarity and crispness. Nice work on getting such a deep DOF. What an incredible capture for being in the wild.</td>', 'Great clarity and crispness. Nice work on getting such a deep DOF. What an incredible capture for being in the wild.', '2009-12-28 19:56:50.000000', NULL, 1),
(5784514, 841975, 60047, '<td valign="top">Nice water patterns. I think you might have done better with a closer crop on one or fewer subjects.</td>', 'Nice water patterns. I think you might have done better with a closer crop on one or fewer subjects.', '2009-12-28 20:02:12.000000', NULL, 1),
(5784564, 841871, 43565, '<td valign="top">I wish he did not look like he was about to fall over backwards.</td>', 'I wish he did not look like he was about to fall over backwards.', '2009-12-28 21:12:09.000000', NULL, 1),
(5784602, 841807, 62895, '<td valign="top">I personally would have cropped this a bit closer and maybe boosted the contrast a bit, but the concept is still really good, and it''s a nice image. 7</td>', 'I personally would have cropped this a bit closer and maybe boosted the contrast a bit, but the concept is still really good, and it''s a nice image. 7', '2009-12-28 21:38:02.000000', NULL, 1),
(5784604, 841084, 62895, '<td valign="top">Most unique I''ve seen yet. Fav so far. Nice Job. 9</td>', 'Most unique I''ve seen yet. Fav so far. Nice Job. 9', '2009-12-28 21:40:02.000000', NULL, 1),
(5784606, 841851, 42100, '<td valign="top">This is really rich in color, tone and detail...very nice bird portrait!</td>', 'This is really rich in color, tone and detail...very nice bird portrait!', '2009-12-28 21:42:16.000000', NULL, 1),
(5784612, 841836, 42100, '<td valign="top">LOL...hmmm...seems to be a domestic species as well as in some kind of enclosure!?!  ;)</td>', 'LOL...hmmm...seems to be a domestic species as well as in some kind of enclosure!?!  ;)', '2009-12-28 21:45:45.000000', NULL, 1),
(5784616, 841830, 42100, '<td valign="top">Nice rich greens in the surrounding vegetation...perfect background blur to set off that crisp detail in the dove.  Well done!</td>', 'Nice rich greens in the surrounding vegetation...perfect background blur to set off that crisp detail in the dove.  Well done!', '2009-12-28 21:50:18.000000', NULL, 1),
(5784620, 841716, 42100, '<td valign="top">Great lighting and wonderful detail...the feather fluffing action makes this a standout in this challenge.  Nicely done!</td>', 'Great lighting and wonderful detail...the feather fluffing action makes this a standout in this challenge.  Nicely done!', '2009-12-28 21:51:50.000000', NULL, 1),
(5784623, 841663, 42100, '<td valign="top">Nice mid-air capture...this guy really pops against that wonderfully blurred background!</td>', 'Nice mid-air capture...this guy really pops against that wonderfully blurred background!', '2009-12-28 21:53:23.000000', NULL, 1),
(5784624, 841530, 42100, '<td valign="top">Nice tones and detail in this fine feathered portrait!</td>', 'Nice tones and detail in this fine feathered portrait!', '2009-12-28 21:54:34.000000', NULL, 1),
(5784631, 841038, 42100, '<td valign="top">I really like this environmental portrait...it really adds more interest and even a little bit of moodiness to this photo.  Nicely done!</td>', 'I really like this environmental portrait...it really adds more interest and even a little bit of moodiness to this photo.  Nicely done!', '2009-12-28 22:03:42.000000', NULL, 1),
(5784646, 841799, 42100, '<td valign="top">That''s one crazy looking duck there...very nice close-up.  Great detail in this portrait!</td>', 'That''s one crazy looking duck there...very nice close-up.  Great detail in this portrait!', '2009-12-28 22:18:44.000000', NULL, 1),
(5784649, 841513, 42100, '<td valign="top">The lighting here is great and I really like the unusual tones.  Very nice photo!</td>', 'The lighting here is great and I really like the unusual tones.  Very nice photo!', '2009-12-28 22:21:39.000000', NULL, 1),
(5784650, 841319, 42100, '<td valign="top">Nice DoF on this photo...the cardinal really stands out against it.</td>', 'Nice DoF on this photo...the cardinal really stands out against it.', '2009-12-28 22:23:32.000000', NULL, 1),
(5784654, 841963, 112828, '<td valign="top">Very nice, there''s no doubt this one is not tethered.  Also, I like the crop here and the colors... This is a very nice image that fits all requirements of this challenge- no doubt it''s a portrait, and no doubt it''s wild...  Yep, you''ve got a killer here, I hope this manages to ribbon, but the competition here is going to be STIFF!</td>', 'Very nice, there''s no doubt this one is not tethered.  Also, I like the crop here and the colors... This is a very nice image that fits all requirements of this challenge- no doubt it''s a portrait, and no doubt it''s wild...  Yep, you''ve got a killer here, I hope this manages to ribbon, but the competition here is going to be STIFF!', '2009-12-28 22:26:33.000000', NULL, 1),
(5784655, 841877, 112828, '<td valign="top">Very neat image... I hope it ribbons.</td>', 'Very neat image... I hope it ribbons.', '2009-12-28 22:26:36.000000', NULL, 1),
(5784656, 841615, 112828, '<td valign="top">Very cool!  This is one of my favorite images from this challenge!</td>', 'Very cool!  This is one of my favorite images from this challenge!', '2009-12-28 22:26:48.000000', NULL, 1),
(5784657, 841084, 42100, '<td valign="top">The high-key and motion blur in the wings really work together well to give this photo a life of its own.  Well done!</td>', 'The high-key and motion blur in the wings really work together well to give this photo a life of its own.  Well done!', '2009-12-28 22:27:12.000000', NULL, 1),
(5784660, 841998, 112828, '<td valign="top">Nice shot, nearly perfect exposure and great shutter speed choice.</td>', 'Nice shot, nearly perfect exposure and great shutter speed choice.', '2009-12-28 22:29:03.000000', NULL, 1),
(5784661, 841830, 112828, '<td valign="top">Isn''t is neat how birds instinctively position themselves directly behind something that will mess up the shot?  Really nice DOF, and the feather detail is great!  Bokeh is beautiful as well.</td>', 'Isn''t is neat how birds instinctively position themselves directly behind something that will mess up the shot?  Really nice DOF, and the feather detail is great!  Bokeh is beautiful as well.', '2009-12-28 22:29:16.000000', NULL, 1),
(5784662, 841966, 112828, '<td valign="top">Nice shot, clean and crisp.  I particularly like the eye and the water on the feathers.  Well done.</td>', 'Nice shot, clean and crisp.  I particularly like the eye and the water on the feathers.  Well done.', '2009-12-28 22:29:20.000000', NULL, 1),
(5784665, 841326, 112828, '<td valign="top">Very well done...  DOF could have been just a wee bit better.  Exposure is very well balanced, thanks for that, so many people have just absolutely blown out the highlights of their birds in this challenge.</td>', 'Very well done...  DOF could have been just a wee bit better.  Exposure is very well balanced, thanks for that, so many people have just absolutely blown out the highlights of their birds in this challenge.', '2009-12-28 22:29:44.000000', NULL, 1),
(5784667, 841659, 112828, '<td valign="top">Very nice, I want to know more!  The image is exposed wonderfully, even if the little white feathers under the wing are blown out.  The shutter speed is perfect, and the bird is clearly looking at the camera.  Well done.</td>', 'Very nice, I want to know more!  The image is exposed wonderfully, even if the little white feathers under the wing are blown out.  The shutter speed is perfect, and the bird is clearly looking at the camera.  Well done.', '2009-12-28 22:30:07.000000', NULL, 1),
(5784668, 841878, 112828, '<td valign="top">Well done, a very sharp shot without distractions.</td>', 'Well done, a very sharp shot without distractions.', '2009-12-28 22:30:10.000000', NULL, 1),
