(5785165, 841597, 60047, '<td valign="top">I love the darkness of this. I wish I could figure out what was going on with the bird. The title didn''t help. Is Alfred Hitchcock around?!</td>', 'I love the darkness of this. I wish I could figure out what was going on with the bird. The title didn''t help. Is Alfred Hitchcock around?!', '2009-12-29 10:14:50.000000', NULL, 1),
(5785168, 841960, 60047, '<td valign="top">These are such beautifully colored birds. Nice capture - though I think either a crisper focus or more sharpening in PP would help.</td>', 'These are such beautifully colored birds. Nice capture - though I think either a crisper focus or more sharpening in PP would help.', '2009-12-29 10:16:16.000000', NULL, 1),
(5785172, 841849, 60047, '<td valign="top">A great pose. Just a bit noticeably pixelated due to the tight crop - though not bad.</td>', 'A great pose. Just a bit noticeably pixelated due to the tight crop - though not bad.', '2009-12-29 10:18:14.000000', NULL, 1),
(5785175, 841853, 60047, '<td valign="top">Interesting use of the short DOF.</td>', 'Interesting use of the short DOF.', '2009-12-29 10:19:22.000000', NULL, 1),
