(5785186, 841968, 60047, '<td valign="top">The focus seems to be just a little soft. I think you could have gotten away with a bit more of a saturation boost on your greens and this would have been even better received. I love the BG bokeh.</td>', 'The focus seems to be just a little soft. I think you could have gotten away with a bit more of a saturation boost on your greens and this would have been even better received. I love the BG bokeh.', '2009-12-29 10:27:43.000000', NULL, 1),
(5785189, 841753, 60047, '<td valign="top">Very difficult lighting conditions. I love the depth of the blues on the bird - too bad he''s not in better focus.</td>', 'Very difficult lighting conditions. I love the depth of the blues on the bird - too bad he''s not in better focus.', '2009-12-29 10:29:16.000000', NULL, 1),
(5785190, 841987, 60047, '<td valign="top">What a great pose!</td>', 'What a great pose!', '2009-12-29 10:29:35.000000', NULL, 1),
