(5785820, 841779, 51747, '<td valign="top">A good entry for the challenge. The waves in the water add interest.</td>', 'A good entry for the challenge. The waves in the water add interest.', '2009-12-29 19:12:54.000000', NULL, 1),
(5785822, 841854, 65234, '<td valign="top">Oooh, a Flicker!  I haven''t seen one of those in awhile.  Nice composition; would prefer fewer OOF foreground twigs but realize that probably wasn''t possible.</td>', 'Oooh, a Flicker!  I haven''t seen one of those in awhile.  Nice composition; would prefer fewer OOF foreground twigs but realize that probably wasn''t possible.', '2009-12-29 19:15:01.000000', NULL, 1),
(5785824, 841752, 51747, '<td valign="top">Not the most beautiful birds, but it''s a nice shot of them.</td>', 'Not the most beautiful birds, but it''s a nice shot of them.', '2009-12-29 19:17:49.000000', NULL, 1),
(5785827, 841626, 51747, '<td valign="top">Looks none too happy does it??  hehe  Nice capture.</td>', 'Looks none too happy does it??  hehe  Nice capture.', '2009-12-29 19:21:02.000000', NULL, 1),
(5785832, 841843, 51747, '<td valign="top">To me, this a bit dark. It has a lot of potential.</td>', 'To me, this a bit dark. It has a lot of potential.', '2009-12-29 19:25:06.000000', NULL, 1),
(5785833, 841991, 51747, '<td valign="top">A good shot for the challenge. It looks like you stretched your equipment to the limit.</td>', 'A good shot for the challenge. It looks like you stretched your equipment to the limit.', '2009-12-29 19:26:07.000000', NULL, 1),
(5785834, 841743, 51747, '<td valign="top">Meets the challenge. Good composition.</td>', 'Meets the challenge. Good composition.', '2009-12-29 19:26:40.000000', NULL, 1),
(5785836, 841933, 51747, '<td valign="top">Pretty good shot of the bird. The head is nice and sharp and well exposed. Most of the rest of the image looks a little overexposed and doesn''t really add anything to the shot. Maybe a landscape crop from just below the right foot up to the top?</td>', 'Pretty good shot of the bird. The head is nice and sharp and well exposed. Most of the rest of the image looks a little overexposed and doesn''t really add anything to the shot. Maybe a landscape crop from just below the right foot up to the top?', '2009-12-29 19:31:24.000000', NULL, 1),
(5785844, 841824, 51747, '<td valign="top">Good capture. The light adds some nice color too.</td>', 'Good capture. The light adds some nice color too.', '2009-12-29 19:35:07.000000', NULL, 1),
(5785854, 841621, 106665, '<td valign="top">Great capture, image and mood.</td>', 'Great capture, image and mood.', '2009-12-29 19:42:42.000000', NULL, 1),
(5785855, 841716, 106665, '<td valign="top">Beautiful capture.</td>', 'Beautiful capture.', '2009-12-29 19:44:30.000000', NULL, 1),
(5785856, 841885, 51747, '<td valign="top">It''s a bit difficult to see the ducks. This might do better in a ''Reflections without mirrors'' challenge.</td>', 'It''s a bit difficult to see the ducks. This might do better in a ''Reflections without mirrors'' challenge.', '2009-12-29 19:44:57.000000', NULL, 1),
(5785859, 841664, 106665, '<td valign="top">Great capture. Awesome paning job and the movement of the wings.</td>', 'Great capture. Awesome paning job and the movement of the wings.', '2009-12-29 19:46:55.000000', NULL, 1),
(5785860, 841012, 106665, '<td valign="top">Beautiful colours.</td>', 'Beautiful colours.', '2009-12-29 19:47:35.000000', NULL, 1),
(5785861, 841659, 106665, '<td valign="top">Really great capture.</td>', 'Really great capture.', '2009-12-29 19:48:39.000000', NULL, 1),
(5785862, 841726, 51747, '<td valign="top">It''s a pretty colorful bird. The background is a nice compliment too. The bird is just a little too out of focus to make this a spectacular shot. Nice try.</td>', 'It''s a pretty colorful bird. The background is a nice compliment too. The bird is just a little too out of focus to make this a spectacular shot. Nice try.', '2009-12-29 19:48:40.000000', NULL, 1),
(5785863, 841787, 106665, '<td valign="top">Stunning!</td>', 'Stunning!', '2009-12-29 19:49:28.000000', NULL, 1),
(5785864, 841390, 51747, '<td valign="top">Good subject and well captured. Not sure I like the processing that has turned the plumage an un-natural grainy purple color.</td>', 'Good subject and well captured. Not sure I like the processing that has turned the plumage an un-natural grainy purple color.', '2009-12-29 19:50:30.000000', NULL, 1),
(5785865, 841068, 106665, '<td valign="top">Great capture of a beautiful bird but the colours in background makes this shot for me.</td>', 'Great capture of a beautiful bird but the colours in background makes this shot for me.', '2009-12-29 19:51:21.000000', NULL, 1),
(5785867, 841828, 51747, '<td valign="top">Nice image.</td>', 'Nice image.', '2009-12-29 19:53:07.000000', NULL, 1),
(5785869, 841615, 106665, '<td valign="top">Excellent capture. I really love how you have captured the movement of the wather, on and around the duck.</td>', 'Excellent capture. I really love how you have captured the movement of the wather, on and around the duck.', '2009-12-29 19:53:14.000000', NULL, 1),
(5785871, 841946, 106665, '<td valign="top">Awesome shot.</td>', 'Awesome shot.', '2009-12-29 19:54:21.000000', NULL, 1),
(5785872, 841836, 106665, '<td valign="top">Great idea!</td>', 'Great idea!', '2009-12-29 19:54:55.000000', NULL, 1),
(5785875, 841732, 106665, '<td valign="top">Very well done.</td>', 'Very well done.', '2009-12-29 19:57:12.000000', NULL, 1),
(5785877, 841578, 51747, '<td valign="top">Nice capture.</td>', 'Nice capture.', '2009-12-29 19:59:57.000000', NULL, 1),
(5785879, 841635, 51747, '<td valign="top">Black and white works well here. Just a little soft or this would be one of the better shots in the challenge.</td>', 'Black and white works well here. Just a little soft or this would be one of the better shots in the challenge.', '2009-12-29 20:02:05.000000', NULL, 1),
(5785885, 841869, 51747, '<td valign="top">Good capture.</td>', 'Good capture.', '2009-12-29 20:07:45.000000', NULL, 1),
(5785890, 841941, 51747, '<td valign="top">Nice one!</td>', 'Nice one!', '2009-12-29 20:12:00.000000', NULL, 1),
(5785897, 841759, 51747, '<td valign="top">Good one. Maybe the reflections draw too much attention from the bird?</td>', 'Good one. Maybe the reflections draw too much attention from the bird?', '2009-12-29 20:15:35.000000', NULL, 1),
(5785903, 841524, 51747, '<td valign="top">not really. Too much forest not enough Dove.</td>', 'not really. Too much forest not enough Dove.', '2009-12-29 20:18:18.000000', NULL, 1),
(5785920, 841853, 51747, '<td valign="top">Pretty neat. I wish the eyes were in focus.</td>', 'Pretty neat. I wish the eyes were in focus.', '2009-12-29 20:24:09.000000', NULL, 1),
(5785922, 841621, 51747, '<td valign="top">Very dramatic. The Heron is just a bit soft.</td>', 'Very dramatic. The Heron is just a bit soft.', '2009-12-29 20:25:19.000000', NULL, 1),
(5785924, 841836, 51747, '<td valign="top">Points for thinking outside the box (but not too many).</td>', 'Points for thinking outside the box (but not too many).', '2009-12-29 20:28:05.000000', NULL, 1),
(5785931, 841543, 51747, '<td valign="top">Nice capture. Not quite up to some of the top images in this challenge. I think you didn''t have enough lens or megapixels.</td>', 'Nice capture. Not quite up to some of the top images in this challenge. I think you didn''t have enough lens or megapixels.', '2009-12-29 20:30:51.000000', NULL, 1),
(5785939, 841522, 51747, '<td valign="top">Interesting choice of presentation.</td>', 'Interesting choice of presentation.', '2009-12-29 20:32:23.000000', NULL, 1),
(5785942, 841691, 25773, '<td valign="top">picture perfect.<br/> <br/>Only the wire makes it a bit ''less wild''.</td>', 'picture perfect. Only the wire makes it a bit ''less wild''.', '2009-12-29 20:34:26.000000', NULL, 1),
(5785947, 841878, 51747, '<td valign="top">Pretty nice capture. Looks like you used a flash? It was a stroke of luck that the bird came so close to you.</td>', 'Pretty nice capture. Looks like you used a flash? It was a stroke of luck that the bird came so close to you.', '2009-12-29 20:36:56.000000', NULL, 1),
(5785948, 841781, 51747, '<td valign="top">Nice capture. It''s a bonus that you have him looking right at you.</td>', 'Nice capture. It''s a bonus that you have him looking right at you.', '2009-12-29 20:36:57.000000', NULL, 1),
(5785949, 841826, 51747, '<td valign="top">Very cool how the Egrets are all looking one direction. Nice capture.</td>', 'Very cool how the Egrets are all looking one direction. Nice capture.', '2009-12-29 20:36:59.000000', NULL, 1),
(5785950, 841801, 51747, '<td valign="top">Nice close up of the bird in flight. There seems to be some noise in the image that takes away from a potentially great shot.</td>', 'Nice close up of the bird in flight. There seems to be some noise in the image that takes away from a potentially great shot.', '2009-12-29 20:37:02.000000', NULL, 1),
(5785954, 841319, 51747, '<td valign="top">Nice job capturing this beauty!</td>', 'Nice job capturing this beauty!', '2009-12-29 20:37:12.000000', NULL, 1),
(5785955, 841960, 51747, '<td valign="top">Very pretty duck. The focus is nice and sharp.</td>', 'Very pretty duck. The focus is nice and sharp.', '2009-12-29 20:37:23.000000', NULL, 1),
(5785956, 841147, 51747, '<td valign="top">Now that''s up close!  Nice shot.</td>', 'Now that''s up close!  Nice shot.', '2009-12-29 20:37:27.000000', NULL, 1),
(5785957, 841926, 51747, '<td valign="top">Nice portrait.</td>', 'Nice portrait.', '2009-12-29 20:37:29.000000', NULL, 1),
(5785958, 841507, 51747, '<td valign="top">Great capture!</td>', 'Great capture!', '2009-12-29 20:37:35.000000', NULL, 1),
(5785959, 841852, 51747, '<td valign="top">A very nice image.</td>', 'A very nice image.', '2009-12-29 20:37:40.000000', NULL, 1),
(5785962, 841946, 51747, '<td valign="top">Very nice processing.</td>', 'Very nice processing.', '2009-12-29 20:37:50.000000', NULL, 1),
(5785965, 841877, 51747, '<td valign="top">Neat image. The vignette works here.</td>', 'Neat image. The vignette works here.', '2009-12-29 20:37:56.000000', NULL, 1),
(5785966, 841485, 51747, '<td valign="top">This is just too funny! Perfect title too.</td>', 'This is just too funny! Perfect title too.', '2009-12-29 20:37:58.000000', NULL, 1),
(5785967, 841951, 51747, '<td valign="top">Nice capture. Beautiful pose.</td>', 'Nice capture. Beautiful pose.', '2009-12-29 20:37:59.000000', NULL, 1),
(5785968, 841649, 51747, '<td valign="top">Very nice shot of this bird. That water sure is blue!!</td>', 'Very nice shot of this bird. That water sure is blue!!', '2009-12-29 20:38:03.000000', NULL, 1),
(5785970, 841980, 51747, '<td valign="top">Very pretty image. It''s just a little soft but a perfect entry for this challenge.</td>', 'Very pretty image. It''s just a little soft but a perfect entry for this challenge.', '2009-12-29 20:38:17.000000', NULL, 1),
(5785971, 841326, 51747, '<td valign="top">She sent you a beauty! Nicely done.</td>', 'She sent you a beauty! Nicely done.', '2009-12-29 20:38:22.000000', NULL, 1),
(5785974, 841993, 51747, '<td valign="top">The title is too funny! Nice capture too.</td>', 'The title is too funny! Nice capture too.', '2009-12-29 20:38:41.000000', NULL, 1),
(5785975, 841830, 51747, '<td valign="top">Lovely Dove. Nice details and focus.</td>', 'Lovely Dove. Nice details and focus.', '2009-12-29 20:38:42.000000', NULL, 1),
(5785976, 841835, 51747, '<td valign="top">What a beauty!</td>', 'What a beauty!', '2009-12-29 20:38:47.000000', NULL, 1),
