INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5785982, 841818, 51747, '<td valign="top">Love the colors and details in the Finch.</td>', 'Love the colors and details in the Finch.', '2009-12-29 20:39:02.000000', NULL, 1),
(5785983, 841615, 51747, '<td valign="top">Great capture of the duck and the water!</td>', 'Great capture of the duck and the water!', '2009-12-29 20:39:03.000000', NULL, 1),
(5785986, 841396, 51747, '<td valign="top">A very nice capture of this bird in a typical pose. Set off by a nice background.</td>', 'A very nice capture of this bird in a typical pose. Set off by a nice background.', '2009-12-29 20:39:15.000000', NULL, 1),
(5785987, 841851, 51747, '<td valign="top">Amazing light here. Nicely captured as well. I think I might have cropped some off the top.</td>', 'Amazing light here. Nicely captured as well. I think I might have cropped some off the top.', '2009-12-29 20:39:16.000000', NULL, 1),
(5785990, 841966, 51747, '<td valign="top">Nice sharp shot. Well done.</td>', 'Nice sharp shot. Well done.', '2009-12-29 20:39:28.000000', NULL, 1),
(5785991, 841963, 51747, '<td valign="top">I like the colors here. There is a real abstract artsy feel to this. Nice capture of the stork too.</td>', 'I like the colors here. There is a real abstract artsy feel to this. Nice capture of the stork too.', '2009-12-29 20:39:29.000000', NULL, 1),
(5785992, 841408, 51747, '<td valign="top">Wonderful sharpness and detail. Cool bokeh.</td>', 'Wonderful sharpness and detail. Cool bokeh.', '2009-12-29 20:39:33.000000', NULL, 1),
(5785993, 841584, 51747, '<td valign="top">Great capture. Nice timing to show the best this bird has to offer. It looks like this was taken from very far away. A difficult challenge indeed.</td>', 'Great capture. Nice timing to show the best this bird has to offer. It looks like this was taken from very far away. A difficult challenge indeed.', '2009-12-29 20:39:47.000000', NULL, 1),
(5785995, 841664, 51747, '<td valign="top">Excellent use of panning in this image. Nice colors too. Just the right amount of blur in the wings to make this a very strong entry in this challenge.</td>', 'Excellent use of panning in this image. Nice colors too. Just the right amount of blur in the wings to make this a very strong entry in this challenge.', '2009-12-29 20:39:50.000000', NULL, 1),
(5785996, 841530, 51747, '<td valign="top">I really like all the textures that you have captured.</td>', 'I really like all the textures that you have captured.', '2009-12-29 20:39:52.000000', NULL, 1),
(5785997, 841632, 51747, '<td valign="top">Well done!</td>', 'Well done!', '2009-12-29 20:39:57.000000', NULL, 1),
(5785998, 841686, 51747, '<td valign="top">Such is the way of nature. A very good find. May be a bit macabre for some voters but I like it.</td>', 'Such is the way of nature. A very good find. May be a bit macabre for some voters but I like it.', '2009-12-29 20:40:00.000000', NULL, 1),
(5786001, 841513, 51747, '<td valign="top">Very interesting choice of processing. May not agree with some voters. I like it!</td>', 'Very interesting choice of processing. May not agree with some voters. I like it!', '2009-12-29 20:40:20.000000', NULL, 1),
(5786002, 841942, 51747, '<td valign="top">Very nice!</td>', 'Very nice!', '2009-12-29 20:40:22.000000', NULL, 1),
(5786005, 841723, 51747, '<td valign="top">Wow!  That''s an awesome duck and some really cool looking water.</td>', 'Wow!  That''s an awesome duck and some really cool looking water.', '2009-12-29 20:40:40.000000', NULL, 1),
(5786006, 841741, 51747, '<td valign="top">Just a great image.</td>', 'Just a great image.', '2009-12-29 20:40:41.000000', NULL, 1),
(5786009, 841825, 51747, '<td valign="top">Excellent details.</td>', 'Excellent details.', '2009-12-29 20:40:54.000000', NULL, 1),
(5786010, 841732, 51747, '<td valign="top">Almost perfect!</td>', 'Almost perfect!', '2009-12-29 20:40:55.000000', NULL, 1),
(5786011, 841656, 51747, '<td valign="top">Really nice.  I love the black sky.</td>', 'Really nice.  I love the black sky.', '2009-12-29 20:40:59.000000', NULL, 1),
(5786012, 841421, 51747, '<td valign="top">Awesome shot!</td>', 'Awesome shot!', '2009-12-29 20:41:06.000000', NULL, 1),
(5786013, 841888, 51747, '<td valign="top">Nice close up!</td>', 'Nice close up!', '2009-12-29 20:41:11.000000', NULL, 1),
(5786016, 841498, 51747, '<td valign="top">Great capture!</td>', 'Great capture!', '2009-12-29 20:41:18.000000', NULL, 1),
(5786017, 841645, 51747, '<td valign="top">Love your choice of processing and orientation.</td>', 'Love your choice of processing and orientation.', '2009-12-29 20:41:19.000000', NULL, 1),
(5786018, 841827, 51747, '<td valign="top">Very nice!</td>', 'Very nice!', '2009-12-29 20:41:22.000000', NULL, 1),
(5786019, 841084, 51747, '<td valign="top">Just great!</td>', 'Just great!', '2009-12-29 20:41:26.000000', NULL, 1),
(5786020, 841874, 51747, '<td valign="top">Wonderful</td>', 'Wonderful', '2009-12-29 20:41:30.000000', NULL, 1),
(5786021, 841911, 51747, '<td valign="top">Excellent!</td>', 'Excellent!', '2009-12-29 20:41:35.000000', NULL, 1),
(5786024, 841643, 51747, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2009-12-29 20:41:46.000000', NULL, 1),
(5786028, 841856, 51747, '<td valign="top">Awesome shot!</td>', 'Awesome shot!', '2009-12-29 20:42:06.000000', NULL, 1),
(5786032, 841716, 51747, '<td valign="top">This is really nice. Just a little tighter crop would make this one of the best of the challenge!</td>', 'This is really nice. Just a little tighter crop would make this one of the best of the challenge!', '2009-12-29 20:42:11.000000', NULL, 1),
(5786033, 841735, 51747, '<td valign="top">Cool colors and nice composition add to this excellent image. Well done.</td>', 'Cool colors and nice composition add to this excellent image. Well done.', '2009-12-29 20:42:13.000000', NULL, 1),
(5786034, 841799, 51747, '<td valign="top">Very nice detail and colors here. It looks like he wants your sandwich. ;)</td>', 'Very nice detail and colors here. It looks like he wants your sandwich. ;)', '2009-12-29 20:42:15.000000', NULL, 1),
(5786037, 841787, 51747, '<td valign="top">Love the processing. Adding to faves.</td>', 'Love the processing. Adding to faves.', '2009-12-29 20:42:26.000000', NULL, 1),
(5786038, 841012, 51747, '<td valign="top">I think this might be the best Bluejay image I have seen here. Very nice indeed.</td>', 'I think this might be the best Bluejay image I have seen here. Very nice indeed.', '2009-12-29 20:42:27.000000', NULL, 1),
(5786043, 841858, 51747, '<td valign="top">How cool is that!!! One of my faves of the challenge!</td>', 'How cool is that!!! One of my faves of the challenge!', '2009-12-29 20:42:35.000000', NULL, 1),
(5786047, 841659, 51747, '<td valign="top">Amazing shot. The fact that the bird is looking at you really makes this image. Well done!</td>', 'Amazing shot. The fact that the bird is looking at you really makes this image. Well done!', '2009-12-29 20:42:49.000000', NULL, 1),
(5786048, 841871, 51747, '<td valign="top">I hope there was ''pun'' intended. hehe Very nicely captured bird. The tilt adds interest IMO</td>', 'I hope there was ''pun'' intended. hehe Very nicely captured bird. The tilt adds interest IMO', '2009-12-29 20:42:50.000000', NULL, 1),
(5786049, 841559, 51747, '<td valign="top">I love this! The contrast between the bird and the wonderful looking water is superb!</td>', 'I love this! The contrast between the bird and the wonderful looking water is superb!', '2009-12-29 20:42:56.000000', NULL, 1),
(5786050, 841078, 51747, '<td valign="top">Awesome capture. Love the DOF you have here. Nice color contrast between the bird and it''s surroundings.</td>', 'Awesome capture. Love the DOF you have here. Nice color contrast between the bird and it''s surroundings.', '2009-12-29 20:43:05.000000', NULL, 1),
(5786054, 841886, 51747, '<td valign="top">WOW That''s gorgeous!  Nice and close. Lucky you. One of the best ''portraits'' in the challenge.</td>', 'WOW That''s gorgeous!  Nice and close. Lucky you. One of the best ''portraits'' in the challenge.', '2009-12-29 20:43:19.000000', NULL, 1),
(5786057, 841663, 51747, '<td valign="top">Really amazing clarity for a moving subject. Nice job!</td>', 'Really amazing clarity for a moving subject. Nice job!', '2009-12-29 20:43:25.000000', NULL, 1),
(5786061, 841910, 51747, '<td valign="top">I''d love to see the lens that captured this awesome shot! Or you were very lucky and the bird let you get real close, hehe  One of the best of the challenge.</td>', 'I''d love to see the lens that captured this awesome shot! Or you were very lucky and the bird let you get real close, hehe  One of the best of the challenge.', '2009-12-29 20:43:34.000000', NULL, 1),
(5786064, 841691, 51747, '<td valign="top">Nice close up. Lots of character and detail.</td>', 'Nice close up. Lots of character and detail.', '2009-12-29 20:43:42.000000', NULL, 1),
(5786065, 841595, 51747, '<td valign="top">Very nice ''head and shoulders'' portrait. It looks like this was taken from a close distance or else there was some serious glass involved here. One of the best of the challenge.</td>', 'Very nice ''head and shoulders'' portrait. It looks like this was taken from a close distance or else there was some serious glass involved here. One of the best of the challenge.', '2009-12-29 20:43:44.000000', NULL, 1),
(5786066, 841237, 25773, '<td valign="top">The colors are nice, but some of the highlights are washed out. The almost centered composition for the duck in focus does not work well for me, as he is looking away, out of the picture.</td>', 'The colors are nice, but some of the highlights are washed out. The almost centered composition for the duck in focus does not work well for me, as he is looking away, out of the picture.', '2009-12-29 20:44:00.000000', NULL, 1),
(5786069, 841963, 25773, '<td valign="top">Very nice colors; I am not sure if I like the feet blurred by the grass... actually, I do! An artistic stork.</td>', 'Very nice colors; I am not sure if I like the feet blurred by the grass... actually, I do! An artistic stork.', '2009-12-29 20:48:51.000000', NULL, 1),
(5786072, 841559, 25773, '<td valign="top">Wow, that''s sharp! Maybe a little too much: you got those dark contour lines on the upper edges of the bird.</td>', 'Wow, that''s sharp! Maybe a little too much: you got those dark contour lines on the upper edges of the bird.', '2009-12-29 20:51:41.000000', NULL, 1),
(5786074, 841835, 25773, '<td valign="top">Neat little fellow. A little more contrast might have brought him out even better... or maybe just having the head sharper (like the legs).</td>', 'Neat little fellow. A little more contrast might have brought him out even better... or maybe just having the head sharper (like the legs).', '2009-12-29 20:56:55.000000', NULL, 1),
(5786075, 841716, 23098, '<td valign="top">This is a beautiful shot. A small crop at the top (some of the reflections) might even enhance the subject more.</td>', 'This is a beautiful shot. A small crop at the top (some of the reflections) might even enhance the subject more.', '2009-12-29 20:57:23.000000', NULL, 1),
(5786078, 841933, 25773, '<td valign="top">Fantastic shot! I wonder how much cropping you needed to fill up the frame this much. Everything is spot-on sharp and well-lit.</td>', 'Fantastic shot! I wonder how much cropping you needed to fill up the frame this much. Everything is spot-on sharp and well-lit.', '2009-12-29 21:00:13.000000', NULL, 1),
(5786081, 841998, 25773, '<td valign="top">Man, how much time does it take to get such a shot? Even though the eagle''s head is not the sharpest, I would be proud for life if I got such a capture.</td>', 'Man, how much time does it take to get such a shot? Even though the eagle''s head is not the sharpest, I would be proud for life if I got such a capture.', '2009-12-29 21:05:34.000000', NULL, 1),
(5786086, 841986, 25773, '<td valign="top">It''s very dark on my screen. Looks interesting though...</td>', 'It''s very dark on my screen. Looks interesting though...', '2009-12-29 21:09:12.000000', NULL, 1),
(5786090, 841759, 25773, '<td valign="top">Very nicely captured! I love the colors and reflections. The centered composition works real well here.</td>', 'Very nicely captured! I love the colors and reflections. The centered composition works real well here.', '2009-12-29 21:11:49.000000', NULL, 1),
(5786148, 841681, 65234, '<td valign="top">Rather a stark environment for the poor bird.  Not sure what I think about the heavy vignette.</td>', 'Rather a stark environment for the poor bird.  Not sure what I think about the heavy vignette.', '2009-12-29 22:30:36.000000', NULL, 1),
