(5786900, 841759, 30982, '<td valign="top">Love the tentativeness of the step - watching to see if the ice is going to crack.</td>', 'Love the tentativeness of the step - watching to see if the ice is going to crack.', '2009-12-30 10:36:39.000000', NULL, 1),
(5786904, 841635, 30982, '<td valign="top">This may not be perfect crisp focus and bold cheeful color, but it is indeed one of my favorites of this challenge.  There''s something both proud and sad about the way this bird holds himself.  The softness, the stark composition and lovely blurred background all contribute to the melancholy feel.</td>', 'This may not be perfect crisp focus and bold cheeful color, but it is indeed one of my favorites of this challenge.  There''s something both proud and sad about the way this bird holds himself.  The softness, the stark composition and lovely blurred background all contribute to the melancholy feel.', '2009-12-30 10:38:12.000000', NULL, 1),
(5786905, 841963, 30982, '<td valign="top">Wonderful color.</td>', 'Wonderful color.', '2009-12-30 10:38:21.000000', NULL, 1),
(5786908, 841799, 30982, '<td valign="top">This guy looks ever so proud!  We may think they''re funny looking - ugly, even - but he thinks he''s a stud, and by Muscovy standards, he probably is!  Great portrait of the guy.</td>', 'This guy looks ever so proud!  We may think they''re funny looking - ugly, even - but he thinks he''s a stud, and by Muscovy standards, he probably is!  Great portrait of the guy.', '2009-12-30 10:39:30.000000', NULL, 1),
(5786910, 841084, 30982, '<td valign="top">Excellent high key work.</td>', 'Excellent high key work.', '2009-12-30 10:39:53.000000', NULL, 1),
(5786911, 841878, 30982, '<td valign="top">Very sweet!</td>', 'Very sweet!', '2009-12-30 10:40:07.000000', NULL, 1),
(5786912, 841038, 30982, '<td valign="top">Gorgeous capture - excellent supporting environment.</td>', 'Gorgeous capture - excellent supporting environment.', '2009-12-30 10:40:29.000000', NULL, 1),
(5786913, 841621, 30982, '<td valign="top">I love how this guy looks totally skeletal.</td>', 'I love how this guy looks totally skeletal.', '2009-12-30 10:40:43.000000', NULL, 1),
(5786914, 841851, 30982, '<td valign="top">Excellent light and detail - fine capture!</td>', 'Excellent light and detail - fine capture!', '2009-12-30 10:40:56.000000', NULL, 1),
(5786917, 841513, 30982, '<td valign="top">I quite love the brightness of this, the warmth of the cool color scheme, and the curious pose of the bird.  Lovely shot!</td>', 'I quite love the brightness of this, the warmth of the cool color scheme, and the curious pose of the bird.  Lovely shot!', '2009-12-30 10:41:20.000000', NULL, 1),
(5786918, 841528, 30982, '<td valign="top">Indeed - a very colorful and elegant ornament!</td>', 'Indeed - a very colorful and elegant ornament!', '2009-12-30 10:41:34.000000', NULL, 1),
