(5787057, 841980, 66384, '<td valign="top">It''s always hard to capture these white birds without blowing out the highlights. I usually keep my exposure stepped down 1/3. It seems to preserve more detail.</td>', 'It''s always hard to capture these white birds without blowing out the highlights. I usually keep my exposure stepped down 1/3. It seems to preserve more detail.', '2009-12-30 11:57:13.000000', NULL, 1),
(5787061, 841955, 66384, '<td valign="top">Love the glistening ice. The bird silhouette stands out so well. Nice composition too.</td>', 'Love the glistening ice. The bird silhouette stands out so well. Nice composition too.', '2009-12-30 11:58:33.000000', NULL, 1),
(5787063, 841998, 66384, '<td valign="top">Wonderful shot. Such clear detail and a beautiful position. Not easy to do!</td>', 'Wonderful shot. Such clear detail and a beautiful position. Not easy to do!', '2009-12-30 11:59:47.000000', NULL, 1),
(5787068, 841543, 66384, '<td valign="top">Very nice capture. Too bad about all the noise. Noise Ninja, Neat Image, or Noiseware would really improve this image.</td>', 'Very nice capture. Too bad about all the noise. Noise Ninja, Neat Image, or Noiseware would really improve this image.', '2009-12-30 12:01:16.000000', NULL, 1),
(5787071, 841615, 66384, '<td valign="top">Lovely detail.</td>', 'Lovely detail.', '2009-12-30 12:01:52.000000', NULL, 1),
(5787079, 841951, 66384, '<td valign="top">Love all those ruffled feathers. Interesting how the little feet seem to be an after-thought. Like who needs legs when you have such wonderful arms? :)</td>', 'Love all those ruffled feathers. Interesting how the little feet seem to be an after-thought. Like who needs legs when you have such wonderful arms? :)', '2009-12-30 12:04:49.000000', NULL, 1),
