(5787746, 841951, 28742, '<td valign="top">Wow! Great wingspan shot!</td>', 'Wow! Great wingspan shot!', '2009-12-30 18:07:15.000000', NULL, 1),
(5787747, 841578, 66384, '<td valign="top">Love the form of this image, and the glow. Very nice and dramatic image.</td>', 'Love the form of this image, and the glow. Very nice and dramatic image.', '2009-12-30 18:07:50.000000', NULL, 1),
(5787748, 841755, 28742, '<td valign="top">Quite the fierce look she''s giving you! :)</td>', 'Quite the fierce look she''s giving you! :)', '2009-12-30 18:07:52.000000', NULL, 1),
(5787749, 841899, 28742, '<td valign="top">Ebony and Ivory... :-)</td>', 'Ebony and Ivory... :-)', '2009-12-30 18:08:34.000000', NULL, 1),
(5787750, 841321, 28742, '<td valign="top">Ahhh darn near perfect!</td>', 'Ahhh darn near perfect!', '2009-12-30 18:08:51.000000', NULL, 1),
(5787751, 841917, 66384, '<td valign="top">Love your composition with the soft vegetation, the gradient of the sun and the outstanding color of the bird. Really well done.</td>', 'Love your composition with the soft vegetation, the gradient of the sun and the outstanding color of the bird. Really well done.', '2009-12-30 18:09:21.000000', NULL, 1),
(5787754, 841530, 66384, '<td valign="top">Love it. That''s some crazy color!</td>', 'Love it. That''s some crazy color!', '2009-12-30 18:10:35.000000', NULL, 1),
(5787758, 841084, 28742, '<td valign="top">WOW! Awesome image!</td>', 'WOW! Awesome image!', '2009-12-30 18:12:49.000000', NULL, 1),
(5787762, 841968, 66384, '<td valign="top">What a pretty setting, and the iridescence is lovely.</td>', 'What a pretty setting, and the iridescence is lovely.', '2009-12-30 18:13:32.000000', NULL, 1),
(5787764, 841485, 28742, '<td valign="top">LOL! Great capture!</td>', 'LOL! Great capture!', '2009-12-30 18:15:02.000000', NULL, 1),
(5787767, 841806, 66384, '<td valign="top">What''s going on with it''s head? I''ve never seen anything like that. Anyway, excellent portrait.</td>', 'What''s going on with it''s head? I''ve never seen anything like that. Anyway, excellent portrait.', '2009-12-30 18:15:59.000000', NULL, 1),
(5787773, 841635, 66384, '<td valign="top">Poor maligned creature. They are so magnificent when they are soaring. This is a great moody shot. The sky really sets him off. Excellent portrait.</td>', 'Poor maligned creature. They are so magnificent when they are soaring. This is a great moody shot. The sky really sets him off. Excellent portrait.', '2009-12-30 18:18:15.000000', NULL, 1),
(5787783, 841522, 66384, '<td valign="top">Lovely image. It has a very oriental feel.</td>', 'Lovely image. It has a very oriental feel.', '2009-12-30 18:21:08.000000', NULL, 1),
(5787788, 841605, 66384, '<td valign="top">How beautiful. Love the little tongue. Great capture of the color and feather detail.</td>', 'How beautiful. Love the little tongue. Great capture of the color and feather detail.', '2009-12-30 18:22:02.000000', NULL, 1),
(5787795, 841926, 66384, '<td valign="top">Lovely light and composition. And I think the DOF is perfect.</td>', 'Lovely light and composition. And I think the DOF is perfect.', '2009-12-30 18:23:59.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5787800, 841321, 66384, '<td valign="top">Very nice capture. Love the color.</td>', 'Very nice capture. Love the color.', '2009-12-30 18:25:09.000000', NULL, 1),
(5787810, 841963, 66384, '<td valign="top">I think the extreme brightness of the foreground distracts from what is a very good shot of the stork. I''d tone down that yellow a bit if it were mine.</td>', 'I think the extreme brightness of the foreground distracts from what is a very good shot of the stork. I''d tone down that yellow a bit if it were mine.', '2009-12-30 18:27:13.000000', NULL, 1),
(5787812, 841528, 66384, '<td valign="top">Before I saw your title, I said it looks like a Christmas tree ornament. I assume you did something extreme to the color, since the pine cones are blue and the bird looks like baked enamel. Still I really like the image.</td>', 'Before I saw your title, I said it looks like a Christmas tree ornament. I assume you did something extreme to the color, since the pine cones are blue and the bird looks like baked enamel. Still I really like the image.', '2009-12-30 18:30:11.000000', NULL, 1),
(5787813, 841078, 66384, '<td valign="top">A beautiful setting for a darling little bird. Nice going!</td>', 'A beautiful setting for a darling little bird. Nice going!', '2009-12-30 18:31:11.000000', NULL, 1),
(5787817, 841735, 66384, '<td valign="top">So is that a gum tree? :) This is so cheerful. I really like it.</td>', 'So is that a gum tree? :) This is so cheerful. I really like it.', '2009-12-30 18:33:32.000000', NULL, 1),
(5787818, 841801, 66384, '<td valign="top">Too bad about the noise. Do you ever use Neat Image or Noise Ninja. It would really improve this very nice capture.</td>', 'Too bad about the noise. Do you ever use Neat Image or Noise Ninja. It would really improve this very nice capture.', '2009-12-30 18:34:53.000000', NULL, 1),
(5787822, 841911, 66384, '<td valign="top">You gotta smile. Love it. And the color is just as soft as the wonderful texture of the bird.</td>', 'You gotta smile. Love it. And the color is just as soft as the wonderful texture of the bird.', '2009-12-30 18:36:20.000000', NULL, 1),
(5787824, 841877, 66384, '<td valign="top">Love how you got this on such a low angle. The colors are marvelous.</td>', 'Love how you got this on such a low angle. The colors are marvelous.', '2009-12-30 18:37:32.000000', NULL, 1),
(5787825, 841663, 66384, '<td valign="top">Stunning.</td>', 'Stunning.', '2009-12-30 18:38:02.000000', NULL, 1),
(5787826, 841326, 66384, '<td valign="top">Well this has to be an omen for your new year. Much happiness to you, whoever you are. This image makes me happy.</td>', 'Well this has to be an omen for your new year. Much happiness to you, whoever you are. This image makes me happy.', '2009-12-30 18:40:23.000000', NULL, 1),
(5787830, 841732, 66384, '<td valign="top">I love how you went all out for the formal portrait look. Well done.</td>', 'I love how you went all out for the formal portrait look. Well done.', '2009-12-30 18:41:53.000000', NULL, 1),
(5787831, 841818, 66384, '<td valign="top">Never saw a house finch look so pretty. It''s a poignant image.</td>', 'Never saw a house finch look so pretty. It''s a poignant image.', '2009-12-30 18:43:10.000000', NULL, 1),
(5787833, 841626, 66384, '<td valign="top">You nailed that little snow bird. Very nice, and I like the tone of your background.</td>', 'You nailed that little snow bird. Very nice, and I like the tone of your background.', '2009-12-30 18:44:30.000000', NULL, 1),
(5787835, 841978, 66384, '<td valign="top">Love the tail, and how you made the one bird stand out from the crowd.</td>', 'Love the tail, and how you made the one bird stand out from the crowd.', '2009-12-30 18:46:03.000000', NULL, 1),
(5787840, 841960, 66384, '<td valign="top">Beautiful bird. I think perhaps this image would benefit from a levels adjustment. I feel as if I am seeing it through a haze.</td>', 'Beautiful bird. I think perhaps this image would benefit from a levels adjustment. I feel as if I am seeing it through a haze.', '2009-12-30 18:48:56.000000', NULL, 1),
(5787842, 841825, 66384, '<td valign="top">Very nice job on a plain bird. The background really complements the color of the subject.</td>', 'Very nice job on a plain bird. The background really complements the color of the subject.', '2009-12-30 18:50:32.000000', NULL, 1),
(5787954, 841626, 105441, '<td valign="top">great focus and comp, excellent shot.</td>', 'great focus and comp, excellent shot.', '2009-12-30 20:50:44.000000', NULL, 1),
(5787960, 841917, 51747, '<td valign="top">Great capture! Too bad it isn''t a closer view of the bird.</td>', 'Great capture! Too bad it isn''t a closer view of the bird.', '2009-12-30 21:01:35.000000', NULL, 1),
(5787986, 841084, 40718, '<td valign="top">I think this is Paul and I''m bumping to a 10.  Best in show.</td>', 'I think this is Paul and I''m bumping to a 10.  Best in show.', '2009-12-30 21:51:21.000000', NULL, 1),
(5788164, 841147, 105555, '<td valign="top">Very nice picture, the colors are very bright...</td>', 'Very nice picture, the colors are very bright...', '2009-12-31 02:03:25.000000', NULL, 1),
(5788166, 841801, 105555, '<td valign="top">Nice shot.  We tend to forget that simples pigeon can be nice subjects.</td>', 'Nice shot.  We tend to forget that simples pigeon can be nice subjects.', '2009-12-31 02:10:05.000000', NULL, 1),
(5788265, 841868, 38478, '<td valign="top">Nice framing with the smaller birds above. I know these are hit and miss, but it would have made a stronger shot if he wasn''t flying away from you. It looks to be a small crop of a larger frame, and loses a lot of detail.</td>', 'Nice framing with the smaller birds above. I know these are hit and miss, but it would have made a stronger shot if he wasn''t flying away from you. It looks to be a small crop of a larger frame, and loses a lot of detail.', '2009-12-31 08:13:05.000000', NULL, 1),
(5788267, 841849, 38478, '<td valign="top">Super shot! The leaf at the bottom is a bit distracting. Since he''s looking to our left, I would have tried to place him at the right side of the photo.</td>', 'Super shot! The leaf at the bottom is a bit distracting. Since he''s looking to our left, I would have tried to place him at the right side of the photo.', '2009-12-31 08:15:16.000000', NULL, 1),
(5788268, 841877, 38478, '<td valign="top">I like the vivid color. The background comes across as very busy.</td>', 'I like the vivid color. The background comes across as very busy.', '2009-12-31 08:16:03.000000', NULL, 1),
(5788274, 841787, 38478, '<td valign="top">I like the motion, I just don''t care for the centered composition.</td>', 'I like the motion, I just don''t care for the centered composition.', '2009-12-31 08:29:28.000000', NULL, 1),
(5788279, 841735, 38478, '<td valign="top">Nicely shot and processed to bring them out of the background. The blue sky under their branch is pretty bright and distracting.</td>', 'Nicely shot and processed to bring them out of the background. The blue sky under their branch is pretty bright and distracting.', '2009-12-31 08:36:15.000000', NULL, 1),
(5788280, 841543, 38478, '<td valign="top">Noisy; but well found, nicely composed shot</td>', 'Noisy; but well found, nicely composed shot', '2009-12-31 08:37:24.000000', NULL, 1),
(5788281, 841852, 38478, '<td valign="top">cool. Well processed to bring out a lot of color in the otherwise bland bg. Not a fan of this type of border...</td>', 'cool. Well processed to bring out a lot of color in the otherwise bland bg. Not a fan of this type of border...', '2009-12-31 08:39:17.000000', NULL, 1),
(5788285, 841528, 38478, '<td valign="top">I don''t understand cropping out his tail.</td>', 'I don''t understand cropping out his tail.', '2009-12-31 08:43:13.000000', NULL, 1),
