(5788503, 841691, 15204, '<td valign="top">I love the backlighting.  Fantastic bokeh.  I think a little more room around him in the frame would have been nice.  Great colors! 7 from me.</td>', 'I love the backlighting.  Fantastic bokeh.  I think a little more room around him in the frame would have been nice.  Great colors! 7 from me.', '2009-12-31 13:09:23.000000', NULL, 1),
(5788508, 841806, 15204, '<td valign="top">The other oof duck in the background really makes the composition IMO.  7 from me.</td>', 'The other oof duck in the background really makes the composition IMO.  7 from me.', '2009-12-31 13:12:32.000000', NULL, 1),
(5788511, 841012, 113274, '<td valign="top">Excellent sharpness and colors, beautiful detail.</td>', 'Excellent sharpness and colors, beautiful detail.', '2009-12-31 13:15:42.000000', NULL, 1),
(5788524, 841686, 88136, '<td valign="top">that is the strangest thing ive seen in quite a while.  is it dead and stuck to the tree? hmmm</td>', 'that is the strangest thing ive seen in quite a while.  is it dead and stuck to the tree? hmmm', '2009-12-31 13:35:51.000000', NULL, 1),
