(5788532, 841421, 35892, '<td valign="top">great capture 10</td>', 'great capture 10', '2009-12-31 13:41:19.000000', NULL, 1),
(5788559, 841852, 47852, '<td valign="top">The green grass in the background seems to not belong in a photo of a frozen lake.  But I do like the fact that it adds some color... an all snow background would be rather bland.</td>', 'The green grass in the background seems to not belong in a photo of a frozen lake.  But I do like the fact that it adds some color... an all snow background would be rather bland.', '2009-12-31 14:28:45.000000', NULL, 1),
(5788561, 841806, 47852, '<td valign="top">That''s quite a hairdo!  I feel like greens are a little over saturated... not just in the blades of grass, but also in the feathers and beak.</td>', 'That''s quite a hairdo!  I feel like greens are a little over saturated... not just in the blades of grass, but also in the feathers and beak.', '2009-12-31 14:29:40.000000', NULL, 1),
(5788563, 841735, 47852, '<td valign="top">Nice portrait of the two birds, but I think the colors are a bit oversaturated.  A tighter crop might have helped to really bring out the textures in those feathers too.</td>', 'Nice portrait of the two birds, but I think the colors are a bit oversaturated.  A tighter crop might have helped to really bring out the textures in those feathers too.', '2009-12-31 14:31:22.000000', NULL, 1),
(5788566, 841787, 47852, '<td valign="top">I like the background patterns here.  It seems as though there is a halo around the entire bird.  At first I thought it might be from the birds forward motion, but that doesn''t explain why it is in front of his wings as well.</td>', 'I like the background patterns here.  It seems as though there is a halo around the entire bird.  At first I thought it might be from the birds forward motion, but that doesn''t explain why it is in front of his wings as well.', '2009-12-31 14:33:53.000000', NULL, 1),
(5788567, 841578, 47852, '<td valign="top">I like the unique perspective and crop here.  Would have been nice to have just a tad more light under the bird though.</td>', 'I like the unique perspective and crop here.  Would have been nice to have just a tad more light under the bird though.', '2009-12-31 14:34:55.000000', NULL, 1),
(5788580, 841886, 47852, '<td valign="top">Wow, I''m drawn into his eye and the interesting black shape around it.  Nice detail in the lower feathers too.  Unfortunately, unless I get my monitor angled just right, the top of his head, and even down his neck, seems a little too saturated and all blends together into a bright reddish blob.</td>', 'Wow, I''m drawn into his eye and the interesting black shape around it.  Nice detail in the lower feathers too.  Unfortunately, unless I get my monitor angled just right, the top of his head, and even down his neck, seems a little too saturated and all blends together into a bright reddish blob.', '2009-12-31 14:40:10.000000', NULL, 1),
(5788583, 841087, 47852, '<td valign="top">Great pose you captured!  Might have cropped this one just a little more to get rid of that lone berry on the left.</td>', 'Great pose you captured!  Might have cropped this one just a little more to get rid of that lone berry on the left.', '2009-12-31 14:43:29.000000', NULL, 1),
(5788586, 841993, 47852, '<td valign="top">Interesting shot, with the two looking in almost the same direction yet facing opposite ways.  The wings spread is great.  And the title adds a nice chuckle.</td>', 'Interesting shot, with the two looking in almost the same direction yet facing opposite ways.  The wings spread is great.  And the title adds a nice chuckle.', '2009-12-31 14:46:34.000000', NULL, 1),
(5788597, 841455, 45928, '<td valign="top">Is this really a wild bird...?</td>', 'Is this really a wild bird...?', '2009-12-31 15:08:51.000000', NULL, 1),
(5788608, 841327, 45928, '<td valign="top">I wish it were more in focus, but very cute.</td>', 'I wish it were more in focus, but very cute.', '2009-12-31 15:23:23.000000', NULL, 1),
(5788672, 841068, 108028, '<td valign="top">just beautiful, love the colors of the picture</td>', 'just beautiful, love the colors of the picture', '2009-12-31 17:05:39.000000', NULL, 1),
(5788767, 841888, 65234, '<td valign="top">In mid-catch, no less.  Superb environmental portrait.</td>', 'In mid-catch, no less.  Superb environmental portrait.', '2009-12-31 19:15:40.000000', NULL, 1),
(5788769, 841910, 65234, '<td valign="top">Extraordinary detail.  Think I would have cropped out the few OOF bits in the foreground.</td>', 'Extraordinary detail.  Think I would have cropped out the few OOF bits in the foreground.', '2009-12-31 19:16:17.000000', NULL, 1),
(5788771, 841595, 65234, '<td valign="top">Gorgeous detail, right down to the shadow of his eyelid and one brilliant catchlight.  Nicely done!</td>', 'Gorgeous detail, right down to the shadow of his eyelid and one brilliant catchlight.  Nicely done!', '2009-12-31 19:17:16.000000', NULL, 1),
(5788773, 841818, 65234, '<td valign="top">LOVE these little guys :-)  Very nice detail here.  Might have cropped out more of the OOF foreground, myself.</td>', 'LOVE these little guys :-)  Very nice detail here.  Might have cropped out more of the OOF foreground, myself.', '2009-12-31 19:18:14.000000', NULL, 1),
(5788785, 841825, 65234, '<td valign="top">Great detail!  Love that cautious eye on you.</td>', 'Great detail!  Love that cautious eye on you.', '2009-12-31 19:27:44.000000', NULL, 1),
(5788786, 841078, 65234, '<td valign="top">What a cool-looking bird!  The red berries and white branches are a nice setting for him.  That white eyering just grabs my eye and pulls me into the image.</td>', 'What a cool-looking bird!  The red berries and white branches are a nice setting for him.  That white eyering just grabs my eye and pulls me into the image.', '2009-12-31 19:28:58.000000', NULL, 1),
