(5791002, 841858, 106349, '<td valign="top">This would have also made a great moon shot!</td>', 'This would have also made a great moon shot!', '2010-01-02 08:16:09.000000', NULL, 1),
(5791003, 841917, 106349, '<td valign="top">Wow, this composition is perfect. One of my high picks.</td>', 'Wow, this composition is perfect. One of my high picks.', '2010-01-02 08:16:32.000000', NULL, 1),
(5791004, 841522, 106349, '<td valign="top">I like the processing on this.</td>', 'I like the processing on this.', '2010-01-02 08:19:08.000000', NULL, 1),
(5791005, 841922, 106349, '<td valign="top">Great b&amp;w!</td>', 'Great b&w!', '2010-01-02 08:19:35.000000', NULL, 1),
(5791205, 841498, 38478, '<td valign="top">Nice crisp shot, background''s a bit busy.</td>', 'Nice crisp shot, background''s a bit busy.', '2010-01-02 11:01:56.000000', NULL, 1),
(5791224, 841732, 38478, '<td valign="top">Good portrait!</td>', 'Good portrait!', '2010-01-02 11:15:28.000000', NULL, 1),
(5791225, 841691, 38478, '<td valign="top">Very nice. I like the way his feet mirror the barbs on the wire</td>', 'Very nice. I like the way his feet mirror the barbs on the wire', '2010-01-02 11:15:32.000000', NULL, 1),
(5791226, 841417, 38478, '<td valign="top">Well done! I like the lines of the branches leading up to him. Eagles in the snow can be fun, because their yellow stands out so well in the otherwise mostly b &amp; w shot.</td>', 'Well done! I like the lines of the branches leading up to him. Eagles in the snow can be fun, because their yellow stands out so well in the otherwise mostly b & w shot.', '2010-01-02 11:15:37.000000', NULL, 1),
(5791228, 841878, 38478, '<td valign="top">Very nice, vivid color and sharp detail. I like the natural framing too.</td>', 'Very nice, vivid color and sharp detail. I like the natural framing too.', '2010-01-02 11:15:45.000000', NULL, 1),
(5791229, 841986, 38478, '<td valign="top">I really like the composition and the feeling of this. Just too dark.</td>', 'I really like the composition and the feeling of this. Just too dark.', '2010-01-02 11:16:06.000000', NULL, 1),
(5791230, 841799, 38478, '<td valign="top">Cheerful, isn''t he? Good detail and lighting.</td>', 'Cheerful, isn''t he? Good detail and lighting.', '2010-01-02 11:16:10.000000', NULL, 1),
(5791231, 841507, 38478, '<td valign="top">Excellent detail. The bg is busy, but I think that works here to show how his natural coloring can blend in.</td>', 'Excellent detail. The bg is busy, but I think that works here to show how his natural coloring can blend in.', '2010-01-02 11:16:15.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5791232, 841998, 38478, '<td valign="top">Well found and captured.</td>', 'Well found and captured.', '2010-01-02 11:16:30.000000', NULL, 1),
(5791431, 841979, 30896, '<td valign="top">The light is beautiful, but the halo (though probably a natural one) makes him like like a sort of cutout. Plus it would be much much better if he were looking towards the camera (not that I would know how to make him to)</td>', 'The light is beautiful, but the halo (though probably a natural one) makes him like like a sort of cutout. Plus it would be much much better if he were looking towards the camera (not that I would know how to make him to)', '2010-01-02 14:26:21.000000', NULL, 1),
(5791441, 841237, 30896, '<td valign="top">I guess it would work better with focus on all three ducks, and may be more of the lovely golden/brown negative space</td>', 'I guess it would work better with focus on all three ducks, and may be more of the lovely golden/brown negative space', '2010-01-02 14:36:40.000000', NULL, 1),
(5791677, 841716, 47852, '<td valign="top">Interesting pose!  I can''t put my finger on why, but I really like the composition of this.  It just feels right.</td>', 'Interesting pose!  I can''t put my finger on why, but I really like the composition of this.  It just feels right.', '2010-01-02 17:19:09.000000', NULL, 1),
(5791678, 841825, 47852, '<td valign="top">Nice use of the shallow dof to get a nice soft background to really show off the details of the feathers.</td>', 'Nice use of the shallow dof to get a nice soft background to really show off the details of the feathers.', '2010-01-02 17:19:23.000000', NULL, 1),
(5792218, 841836, 106543, '<td valign="top">I believe that this bird is on a leash and perched, not sure if that''s allowed...</td>', 'I believe that this bird is on a leash and perched, not sure if that''s allowed...', '2010-01-02 22:20:20.000000', NULL, 1),
(5792228, 841917, 112828, '<td valign="top">Excellent!  What kind of bird is that anyway?  I love the mouse- well done!  Also, the sun is very nice here too.. No doubt this one is wild.</td>', 'Excellent!  What kind of bird is that anyway?  I love the mouse- well done!  Also, the sun is very nice here too.. No doubt this one is wild.', '2010-01-02 22:28:17.000000', NULL, 1),
(5792297, 841530, 6534, '<td valign="top">Beautiful, the best shot I''ve seen in this challenge.  Good luck!</td>', 'Beautiful, the best shot I''ve seen in this challenge.  Good luck!', '2010-01-02 23:11:54.000000', NULL, 1),
(5792319, 841899, 23317, '<td valign="top">Great capture.  My favorite of the challenge.</td>', 'Great capture.  My favorite of the challenge.', '2010-01-02 23:19:46.000000', NULL, 1),
(5792323, 841995, 23317, '<td valign="top">One of the most interesting of the challenge.  In my top 5.</td>', 'One of the most interesting of the challenge.  In my top 5.', '2010-01-02 23:20:13.000000', NULL, 1),
(5792326, 841836, 23317, '<td valign="top">It''ll probably get beat up by this group for not hitting the exact definition, but I greatly enjoyed the interpretation.</td>', 'It''ll probably get beat up by this group for not hitting the exact definition, but I greatly enjoyed the interpretation.', '2010-01-02 23:22:16.000000', NULL, 1),
(5792661, 841741, 52130, '<td valign="top">oooh that''s a longtail. Are you near Bermuda? That''s their national bird. great full-body capture</td>', 'oooh that''s a longtail. Are you near Bermuda? That''s their national bird. great full-body capture', '2010-01-03 05:18:45.000000', NULL, 1),
(5792888, 841886, 65234, '<td valign="top">Beautiful detail and color.  Very pretty bird, too.</td>', 'Beautiful detail and color.  Very pretty bird, too.', '2010-01-03 10:49:44.000000', NULL, 1),
(5792889, 841632, 65234, '<td valign="top">Classic gull shot.</td>', 'Classic gull shot.', '2010-01-03 10:49:50.000000', NULL, 1),
(5792890, 841946, 65234, '<td valign="top">Love the light!</td>', 'Love the light!', '2010-01-03 10:50:07.000000', NULL, 1),
(5792892, 841830, 65234, '<td valign="top">Nicely set off by all the green; pretty shades of blue and gold on the bird.</td>', 'Nicely set off by all the green; pretty shades of blue and gold on the bird.', '2010-01-03 10:50:10.000000', NULL, 1),
(5792894, 841421, 65234, '<td valign="top">Lovely bird!  Very nice detail.  I might play around with making the background greener and a tad more muted so the bird stood out better.</td>', 'Lovely bird!  Very nice detail.  I might play around with making the background greener and a tad more muted so the bird stood out better.', '2010-01-03 10:51:38.000000', NULL, 1),
(5792896, 841987, 65234, '<td valign="top">Funky eye on that bird, and interesting pose.</td>', 'Funky eye on that bird, and interesting pose.', '2010-01-03 10:52:39.000000', NULL, 1),
(5792908, 841643, 65234, '<td valign="top">Nice detail on him.  Much clutter underneath him, which makes for an environmental sort of portrait, but I''d play with a tighter crop or softening the vegetation a bit for this challenge.  Still an excellent shot.</td>', 'Nice detail on him.  Much clutter underneath him, which makes for an environmental sort of portrait, but I''d play with a tighter crop or softening the vegetation a bit for this challenge.  Still an excellent shot.', '2010-01-03 11:02:48.000000', NULL, 1),
(5792910, 841723, 65234, '<td valign="top">Love the golden light on the water; makes his green markings stand out really well.</td>', 'Love the golden light on the water; makes his green markings stand out really well.', '2010-01-03 11:03:50.000000', NULL, 1),
(5792916, 841691, 65234, '<td valign="top">He fills the frame well and the detail is great.  One suggestion:  some dodge and burn to really bring out the catchlight in the eye.  It just looks a little duller than I think it could.</td>', 'He fills the frame well and the detail is great.  One suggestion:  some dodge and burn to really bring out the catchlight in the eye.  It just looks a little duller than I think it could.', '2010-01-03 11:07:27.000000', NULL, 1),
(5792920, 841659, 65234, '<td valign="top">Good flight shot; very intimidating fellow!</td>', 'Good flight shot; very intimidating fellow!', '2010-01-03 11:09:14.000000', NULL, 1),
(5792922, 841162, 65234, '<td valign="top">Road kill (ok; that could be a horrid pun).  Little soft but that''s OK.  I''m seeing as much detail as I need to for this story to be told!</td>', 'Road kill (ok; that could be a horrid pun).  Little soft but that''s OK.  I''m seeing as much detail as I need to for this story to be told!', '2010-01-03 11:10:45.000000', NULL, 1),
(5792930, 841908, 65234, '<td valign="top">Pretty little bird! Nice positioning in the frame.  There is a lot of yellow/green in the branches which camouflages the bird a bit.  I''d mess with reality and either desaturate the branches some or shift their hue toward red/orange to make him stand out more.</td>', 'Pretty little bird! Nice positioning in the frame.  There is a lot of yellow/green in the branches which camouflages the bird a bit.  I''d mess with reality and either desaturate the branches some or shift their hue toward red/orange to make him stand out more.', '2010-01-03 11:15:25.000000', NULL, 1),
(5792932, 841686, 65234, '<td valign="top">He''s dead?  And still clutching the branch?  That''s sad!!</td>', 'He''s dead?  And still clutching the branch?  That''s sad!!', '2010-01-03 11:16:28.000000', NULL, 1),
(5792933, 841942, 65234, '<td valign="top">Cool!  I''ve not seen one of these in person.  Nice light and capture; good placement in the frame.</td>', 'Cool!  I''ve not seen one of these in person.  Nice light and capture; good placement in the frame.', '2010-01-03 11:16:35.000000', NULL, 1),
(5792934, 841920, 65234, '<td valign="top">Skittering about, as they often are.  I like the pinkish cast; makes me think it was sunrise or sunset.</td>', 'Skittering about, as they often are.  I like the pinkish cast; makes me think it was sunrise or sunset.', '2010-01-03 11:16:38.000000', NULL, 1),
(5792936, 841779, 65234, '<td valign="top">Nice patterns in the water there to set him off.  Might dodge a bit to see a catchlight in the eye and more facial detail, but this is very nice.</td>', 'Nice patterns in the water there to set him off.  Might dodge a bit to see a catchlight in the eye and more facial detail, but this is very nice.', '2010-01-03 11:16:41.000000', NULL, 1),
(5792937, 841960, 65234, '<td valign="top">Lovely Wood Duck :-)  They are SUCH cool-looking birds and you did a great job capturing him.</td>', 'Lovely Wood Duck :-)  They are SUCH cool-looking birds and you did a great job capturing him.', '2010-01-03 11:16:44.000000', NULL, 1),
(5792938, 841755, 65234, '<td valign="top">Mama looks like she''s ready to attack if you move one step closer!  Great capture.</td>', 'Mama looks like she''s ready to attack if you move one step closer!  Great capture.', '2010-01-03 11:16:48.000000', NULL, 1),
(5792939, 841513, 65234, '<td valign="top">Cute little Titmouse.  Kind of a dreamy effect, very nice colors.</td>', 'Cute little Titmouse.  Kind of a dreamy effect, very nice colors.', '2010-01-03 11:16:51.000000', NULL, 1),
(5792940, 841716, 65234, '<td valign="top">"Good heavens; what''s that under my wing?!" LOL!  Nice lighting.</td>', '"Good heavens; what''s that under my wing?!" LOL!  Nice lighting.', '2010-01-03 11:16:55.000000', NULL, 1),
(5792941, 841781, 65234, '<td valign="top">Nice color and detail, down to the catchlight in the eye.</td>', 'Nice color and detail, down to the catchlight in the eye.', '2010-01-03 11:17:38.000000', NULL, 1),
(5792942, 841933, 65234, '<td valign="top">Looking a bit fluffed against the cold.  Nice detail.</td>', 'Looking a bit fluffed against the cold.  Nice detail.', '2010-01-03 11:17:43.000000', NULL, 1),
(5792943, 841759, 65234, '<td valign="top">Lovely reflections; I like the tones here.</td>', 'Lovely reflections; I like the tones here.', '2010-01-03 11:17:51.000000', NULL, 1),
(5792944, 841522, 65234, '<td valign="top">Had to come back to this one after thinking on it awhile.  Really different processing, but ... there''s some personality there in the tilt of their heads, and the details of their environment and feathering are plainly evident.  Reminds me a bit of an Oriental woodblock print.  Really quite an interesting image.</td>', 'Had to come back to this one after thinking on it awhile.  Really different processing, but ... there''s some personality there in the tilt of their heads, and the details of their environment and feathering are plainly evident.  Reminds me a bit of an Oriental woodblock print.  Really quite an interesting image.', '2010-01-03 11:18:05.000000', NULL, 1),
(5792946, 841615, 65234, '<td valign="top">Definitely a water bird, that Mallard ;-)  A little more activity than I expect in a portrait, but fun.</td>', 'Definitely a water bird, that Mallard ;-)  A little more activity than I expect in a portrait, but fun.', '2010-01-03 11:18:08.000000', NULL, 1),
(5792948, 841408, 65234, '<td valign="top">Nice flight capture.  Like the rim lighting on his head.</td>', 'Nice flight capture.  Like the rim lighting on his head.', '2010-01-03 11:18:51.000000', NULL, 1),
(5792949, 841917, 65234, '<td valign="top">Cool bird!  Like the light here, too.</td>', 'Cool bird!  Like the light here, too.', '2010-01-03 11:19:00.000000', NULL, 1),
(5792950, 841610, 65234, '<td valign="top">Pretty bird; selective desat isolates him nicely.</td>', 'Pretty bird; selective desat isolates him nicely.', '2010-01-03 11:19:04.000000', NULL, 1),
(5792951, 841521, 65234, '<td valign="top">Too good to be bothered with the likes of us, apparently ;-)  Nice detail.</td>', 'Too good to be bothered with the likes of us, apparently ;-)  Nice detail.', '2010-01-03 11:19:07.000000', NULL, 1),
(5792952, 841528, 65234, '<td valign="top">A colorful ornament at that.  Very pretty.</td>', 'A colorful ornament at that.  Very pretty.', '2010-01-03 11:19:10.000000', NULL, 1),
(5792953, 841856, 65234, '<td valign="top">Wow; great detail on that eye!</td>', 'Wow; great detail on that eye!', '2010-01-03 11:19:13.000000', NULL, 1),
(5792954, 841605, 65234, '<td valign="top">Very pretty bird in a colorful setting.</td>', 'Very pretty bird in a colorful setting.', '2010-01-03 11:19:17.000000', NULL, 1),
(5792955, 841853, 65234, '<td valign="top">Took me a sec to realize what I was looking at ;-)  Actually rather like the exaggerated DOF with that direct eye contact; draws me right in.</td>', 'Took me a sec to realize what I was looking at ;-)  Actually rather like the exaggerated DOF with that direct eye contact; draws me right in.', '2010-01-03 11:19:19.000000', NULL, 1),
(5792956, 841833, 23484, '<td valign="top">Love this shot. Neat color tone.</td>', 'Love this shot. Neat color tone.', '2010-01-03 11:20:03.000000', NULL, 1),
(5792960, 841934, 23484, '<td valign="top">Nice job. It looks good against that beautiful blue sky.</td>', 'Nice job. It looks good against that beautiful blue sky.', '2010-01-03 11:20:49.000000', NULL, 1),
(5793233, 841522, 36102, '<td valign="top">I''m not a big fan of the effect here.</td>', 'I''m not a big fan of the effect here.', '2010-01-03 13:52:21.000000', NULL, 1),
(5793234, 841321, 36102, '<td valign="top">Good Shot, nice placement of the bird in the frame.</td>', 'Good Shot, nice placement of the bird in the frame.', '2010-01-03 13:53:45.000000', NULL, 1),
(5793235, 841507, 36102, '<td valign="top">I like this one.  Love the background with that bird!</td>', 'I like this one.  Love the background with that bird!', '2010-01-03 13:54:11.000000', NULL, 1),
(5793237, 841752, 36102, '<td valign="top">Sorry, it feels a little snapshotish.  If the background could have been blurred more with the birds in sharper focus I think that would have helped.  It''s those darn power lines.</td>', 'Sorry, it feels a little snapshotish.  If the background could have been blurred more with the birds in sharper focus I think that would have helped.  It''s those darn power lines.', '2010-01-03 13:56:10.000000', NULL, 1),
(5793238, 841716, 36102, '<td valign="top">I like the rocks in the bottom of the frame.  Love the bird''s pose, very silly.  Nice ''tone'' to the whole thing.</td>', 'I like the rocks in the bottom of the frame.  Love the bird''s pose, very silly.  Nice ''tone'' to the whole thing.', '2010-01-03 13:56:50.000000', NULL, 1),
(5793241, 841626, 36102, '<td valign="top">Brrrr, that''s one cold little bird.  Very nice, I like it.</td>', 'Brrrr, that''s one cold little bird.  Very nice, I like it.', '2010-01-03 13:57:47.000000', NULL, 1),
(5793242, 841525, 36102, '<td valign="top">I love the spot of bright blue against the tree I just wish there wasn''t so much tree in the picture.</td>', 'I love the spot of bright blue against the tree I just wish there wasn''t so much tree in the picture.', '2010-01-03 13:59:27.000000', NULL, 1),
(5793247, 841012, 36102, '<td valign="top">wow, good job filling the frame with a little bird.</td>', 'wow, good job filling the frame with a little bird.', '2010-01-03 14:00:40.000000', NULL, 1),
(5793251, 841528, 36102, '<td valign="top">I like the placement of the bird and the greenery in the picture.  Great colors too.</td>', 'I like the placement of the bird and the greenery in the picture.  Great colors too.', '2010-01-03 14:02:19.000000', NULL, 1),
(5793253, 841869, 36102, '<td valign="top">I love cardinals.  I wish that branch wasn''t in front of him but it''s a good clear shot of his head!</td>', 'I love cardinals.  I wish that branch wasn''t in front of him but it''s a good clear shot of his head!', '2010-01-03 14:04:19.000000', NULL, 1),
(5793256, 841979, 36102, '<td valign="top">just a sea gull but you made it look so pretty.  Love the color of the sky and the angle you shot it at.</td>', 'just a sea gull but you made it look so pretty.  Love the color of the sky and the angle you shot it at.', '2010-01-03 14:05:52.000000', NULL, 1),
(5793400, 841659, 95065, '<td valign="top">Wow - nice shot!  Sharp face and well isolated from a distracting background.</td>', 'Wow - nice shot!  Sharp face and well isolated from a distracting background.', '2010-01-03 16:33:57.000000', NULL, 1),
(5793403, 841910, 95065, '<td valign="top">Very nice close-up with good detail and sharpness.</td>', 'Very nice close-up with good detail and sharpness.', '2010-01-03 16:34:40.000000', NULL, 1),
(5793407, 841663, 95065, '<td valign="top">Great shot of a wary raptor.  Well isolated from background distractions and great detail in the bird.</td>', 'Great shot of a wary raptor.  Well isolated from background distractions and great detail in the bird.', '2010-01-03 16:35:56.000000', NULL, 1),
(5793411, 841799, 95065, '<td valign="top">Nice headshot with great detail.  The photo is beautiful . . .  can''t necessarily say the same for the bird!</td>', 'Nice headshot with great detail.  The photo is beautiful . . .  can''t necessarily say the same for the bird!', '2010-01-03 16:37:24.000000', NULL, 1),
(5793416, 841851, 95065, '<td valign="top">Beautiful image.  Nice tight composition under good light.</td>', 'Beautiful image.  Nice tight composition under good light.', '2010-01-03 16:39:13.000000', NULL, 1),
(5793418, 841530, 95065, '<td valign="top">Beautiful image of this pelican.  i like the color in bill and the detail in the head</td>', 'Beautiful image of this pelican.  i like the color in bill and the detail in the head', '2010-01-03 16:40:01.000000', NULL, 1),
(5793429, 841933, 95065, '<td valign="top">Very nice shot here.  I like the tight composition and blue background that really makes the bird stand out.</td>', 'Very nice shot here.  I like the tight composition and blue background that really makes the bird stand out.', '2010-01-03 16:44:06.000000', NULL, 1),
(5793431, 841319, 95065, '<td valign="top">Beautiful shot with great detail in the bird''s feathers.  Nicely isolated subject.</td>', 'Beautiful shot with great detail in the bird''s feathers.  Nicely isolated subject.', '2010-01-03 16:44:08.000000', NULL, 1),
(5793433, 841507, 95065, '<td valign="top">Great shot.  I like how the bird is camouflaged so well - in this case a distracting background fits the image.</td>', 'Great shot.  I like how the bird is camouflaged so well - in this case a distracting background fits the image.', '2010-01-03 16:45:17.000000', NULL, 1),
(5793434, 841605, 95065, '<td valign="top">Sooo colorful!  Nice image.</td>', 'Sooo colorful!  Nice image.', '2010-01-03 16:45:48.000000', NULL, 1),
(5793436, 841852, 95065, '<td valign="top">I like the way you incorporated so much of the scenery with the birds in this shot.  It all fits nicely.</td>', 'I like the way you incorporated so much of the scenery with the birds in this shot.  It all fits nicely.', '2010-01-03 16:47:08.000000', NULL, 1),
(5793562, 841998, 82749, '<td valign="top">Wow, nice capture!  (no vote, just making a few comments)</td>', 'Wow, nice capture!  (no vote, just making a few comments)', '2010-01-03 17:57:34.000000', NULL, 1),
(5793568, 841856, 82749, '<td valign="top">Nice details on the body, beak, face!  (no vote, just making a few comments)</td>', 'Nice details on the body, beak, face!  (no vote, just making a few comments)', '2010-01-03 17:58:45.000000', NULL, 1),
(5793573, 841978, 82749, '<td valign="top">Nice midflight capture.  I like the patterns formed by the birds on the ground which is then echoed by the rocks.  (no vote, just making a few comments)</td>', 'Nice midflight capture.  I like the patterns formed by the birds on the ground which is then echoed by the rocks.  (no vote, just making a few comments)', '2010-01-03 18:01:15.000000', NULL, 1),
(5793581, 841663, 82749, '<td valign="top">Excellent sharpness for a bird in mid-flight.  (no vote, just making a few comments)</td>', 'Excellent sharpness for a bird in mid-flight.  (no vote, just making a few comments)', '2010-01-03 18:03:34.000000', NULL, 1),
(5793583, 841485, 82749, '<td valign="top">Very amusing!  (no vote, just making a few comments)</td>', 'Very amusing!  (no vote, just making a few comments)', '2010-01-03 18:03:53.000000', NULL, 1),
(5793587, 841078, 82749, '<td valign="top">Nice details on the bird, like the patterns formed by all of the branches.  (no vote, just making a few comments)</td>', 'Nice details on the bird, like the patterns formed by all of the branches.  (no vote, just making a few comments)', '2010-01-03 18:04:40.000000', NULL, 1),
(5793593, 841781, 82749, '<td valign="top">Great red color.  You might consider cloning out the little twig that is right in front of the bird.  (no vote, just making a few comments)</td>', 'Great red color.  You might consider cloning out the little twig that is right in front of the bird.  (no vote, just making a few comments)', '2010-01-03 18:06:29.000000', NULL, 1),
(5793597, 841799, 82749, '<td valign="top">Excellent details on all parts of the bird.  Different textures of the beak vs feathers vs face is excellent.  Nicely lit as well.  (no vote, just making a few comments)</td>', 'Excellent details on all parts of the bird.  Different textures of the beak vs feathers vs face is excellent.  Nicely lit as well.  (no vote, just making a few comments)', '2010-01-03 18:07:56.000000', NULL, 1),
(5793601, 841801, 82749, '<td valign="top">Nice details and focus, great capture, only quibble is that it is a bit noisy.  (no vote, just making a few comments)</td>', 'Nice details and focus, great capture, only quibble is that it is a bit noisy.  (no vote, just making a few comments)', '2010-01-03 18:09:54.000000', NULL, 1),
